H.background();
const R = Math.max(P.R, 0.1), C = Math.max(P.C, 0.01);
const V0 = 9;
const tau = R * C;
const Tmax = Math.max(5 * tau, 0.5);
const v = H.plot2d({ xMin: 0, xMax: Tmax, yMin: 0, yMax: V0 * 1.15 });
v.grid(); v.axes();
v.fn(x => V0 * (1 - Math.exp(-x / tau)), { color: H.colors.accent, width: 3 });
v.line(tau, 0, tau, V0, { color: H.colors.violet, width: 1.5, dash: [5, 5] });
v.text("tau", tau, V0 * 0.1, { color: H.colors.violet, size: 12 });
const tt = (t % (Tmax)) ;
const Vt = V0 * (1 - Math.exp(-tt / tau));
v.dot(tt, Vt, { r: 7, fill: H.colors.accent2 });
H.text("RC charging: V(t) = V0 (1 - e^(-t/RC))", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("tau = RC = " + tau.toFixed(2) + " s   (63% at t=tau)", 24, 52, { color: H.colors.sub, size: 13 });
